<?php
$upcoming=[];if(schedules_ready())foreach(all("SELECT m.*,c.name category_name FROM menu_items m JOIN categories c ON c.id=m.category_id WHERE m.seller_id=? AND m.status='published' AND c.active=1 AND NOT ".live_sql('m')." ORDER BY m.id",[$s['user_id']]) as $future){$window=window_for($future);if($window&&$window['start']>new DateTimeImmutable('now')){$future['next_start']=$window['start'];$upcoming[]=$future;}}
if($upcoming): ?>
<section class="restaurant-reviews"><div class="page-heading"><span class="heading-kicker"><?=e(t('A LITTLE SOMETHING TO LOOK FORWARD TO'))?></span><h2><?=e(t('Coming Later'))?></h2></div><div class="saved-grid"><?php foreach($upcoming as $future): ?><article class="panel padded"><span class="chip pending"><?=e(t('Not taking orders yet'))?></span><h3><?=e($future['name'])?></h3><p><?=money((int)$future['price_paisa'])?></p><p class="hint"><?=e(t('Available'))?> <?=e(local_time($future['next_start']->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s')))?></p><?=favourite_button('food',(int)$future['id'],'restaurant.php?id='.$s['id'],$future['name'])?></article><?php endforeach ?></div></section><?php endif ?>
